use super::*;

/// A small header with every shape the parser knows, laid out as
/// gen-tag-table.py writes it.
const SAMPLE: &str = r#"/* == Start of generated table == */
/*
 * The following table is generated by running:
 */

#ifndef HB_OT_TAG_TABLE_HH
#define HB_OT_TAG_TABLE_HH

static const LangTag ot_languages2[] = {
  {HB_TAG('a','a',' ',' '),	HB_TAG('A','F','R',' ')},	/* Afar */
  {HB_TAG('m','l',' ',' '),	HB_TAG('M','A','L',' ')},	/* Malayalam */
  {HB_TAG('m','l',' ',' '),	HB_TAG('M','L','R',' ')},	/* Malayalam -> Malayalam Reformed */
};

#ifndef HB_NO_LANGUAGE_LONG
static const hb_tag_t ot_languages3_blocked[] = {
  HB_TAG('a','b','a',' '),	/* Abé != Abaza */
  HB_TAG('z','n','d',' '),	/* Zande */
};

static const LangTag ot_languages3[] = {
  {HB_TAG('a','a','e',' '),	HB_TAG('S','Q','I',' ')},	/* Arbëreshë Albanian -> Albanian */
};

static const hb_tag_t ot_languages3_multi_values[] = {
  HB_TAG('F','A','N',' '),	/* Saint Lucian Creole French -> French Antillean */
  HB_TAG('C','P','P',' '),	/* Saint Lucian Creole French -> Creoles */
};

static const LangTagRange ot_languages3_multi[] = {
  {HB_TAG('a','c','f',' '),	0,	2},	/* Saint Lucian Creole French */
};
#endif

/**
 * hb_ot_tags_from_complex_language:
 **/
static inline bool
hb_ot_tags_from_complex_language (const char   *lang_str,
				  const char   *limit,
				  unsigned int *count /* IN/OUT */,
				  hb_tag_t     *tags /* OUT */)
{
  if (limit - lang_str >= 7)
  {
    const char *p = strchr (lang_str, '-');
    if (!p || p >= limit || limit - p < 5) goto out;
    if (subtag_matches (p, limit, "-fonnapa", 8))
    {
      /* Undetermined; North American Phonetic Alphabet */
      tags[0] = HB_TAG('A','P','P','H');  /* Phonetic transcription—Americanist conventions */
      *count = 1;
      return true;
    }
  }
out:
  switch (lang_str[0])
  {
  case 'a':
    if (0 == strcmp (&lang_str[1], "rt-lojban"))
    {
      /* Lojban (retired code) */
      tags[0] = HB_TAG('J','B','O',' ');  /* Lojban */
      *count = 1;
      return true;
    }
    break;
  case 'c':
    if (lang_matches (&lang_str[1], limit, "do-hant-mo", 10))
    {
      /* Min Dong Chinese; Han (Traditional variant); Macao */
      unsigned int i;
      hb_tag_t possible_tags[] = {
	HB_TAG('Z','H','T','M'),  /* Chinese, Traditional, Macao SAR */
	HB_TAG('Z','H','H',' '),  /* Chinese, Traditional, Hong Kong SAR */
      };
      for (i = 0; i < 2 && i < *count; i++)
	tags[i] = possible_tags[i];
      *count = i;
      return true;
    }
    if (0 == strncmp (&lang_str[1], "do-", 3)
	&& subtag_matches (lang_str, limit, "-hk", 3))
    {
      /* Min Dong Chinese; Hong Kong */
      tags[0] = HB_TAG('Z','H','H',' ');  /* Chinese, Traditional, Hong Kong SAR */
      *count = 1;
      return true;
    }
    break;
  }
  return false;
}

/**
 * hb_ot_ambiguous_tag_to_language
 **/
static inline hb_language_t
hb_ot_ambiguous_tag_to_language (hb_tag_t tag)
{
  switch (tag)
  {
  case HB_TAG('A','L','T',' '):  /* Altai */
    return hb_language_from_string ("alt", -1);  /* Southern Altai */
  case HB_TAG('K','G','E',' '):  /* Khutsuri Georgian */
    return hb_language_from_string ("und-Geok", -1);  /* Undetermined */
  default:
    return HB_LANGUAGE_INVALID;
  }
}

#endif /* HB_OT_TAG_TABLE_HH */

/* == End of generated table == */
"#;

fn t(s: &[u8; 4]) -> Tag4 {
    *s
}

#[test]
fn every_shape_of_the_sample_is_read() {
    let table = parse(SAMPLE).unwrap();
    assert_eq!(
        table.languages2,
        [
            (t(b"aa  "), t(b"AFR ")),
            (t(b"ml  "), t(b"MAL ")),
            (t(b"ml  "), t(b"MLR "))
        ]
    );
    assert_eq!(table.languages3_blocked, [t(b"aba "), t(b"znd ")]);
    assert_eq!(table.languages3, [(t(b"aae "), t(b"SQI "))]);
    assert_eq!(table.multi_values, [t(b"FAN "), t(b"CPP ")]);
    assert_eq!(table.multi, [(t(b"acf "), 0, 2)]);
    assert_eq!(
        table.complex_subtags,
        [("-fonnapa".to_string(), vec![t(b"APPH")])]
    );
    assert_eq!(
        table.complex,
        [
            Branch {
                first: b'a',
                cond: Cond::Exact("rt-lojban".to_string()),
                tags: vec![t(b"JBO ")],
            },
            Branch {
                first: b'c',
                cond: Cond::LangMatches("do-hant-mo".to_string()),
                tags: vec![t(b"ZHTM"), t(b"ZHH ")],
            },
            Branch {
                first: b'c',
                cond: Cond::PrefixSubtag("do-".to_string(), "-hk".to_string()),
                tags: vec![t(b"ZHH ")],
            },
        ]
    );
    assert_eq!(
        table.ambiguous,
        [
            (t(b"ALT "), "alt".to_string()),
            (t(b"KGE "), "und-Geok".to_string())
        ]
    );
}

#[test]
fn the_output_names_every_table_and_branch() {
    let out = emit(&parse(SAMPLE).unwrap(), &["head".to_string()]);
    assert!(out.starts_with("// head\n\nuse crate::tag::{Branch, Cond, t};\n"));
    for want in [
        "pub(crate) const LANGUAGES2: [(u32, u32); 3] = [",
        "    (t(b\"ml  \"), t(b\"MLR \")),",
        "pub(crate) const LANGUAGES3_BLOCKED: [u32; 2] = [",
        "    t(b\"aba \"), t(b\"znd \"),",
        "pub(crate) const LANGUAGES3_MULTI: [(u32, u16, u8); 1] = [",
        "    (t(b\"acf \"), 0, 2),",
        "    (b\"-fonnapa\", &[t(b\"APPH\")]),",
        "    Branch { first: b'a', cond: Cond::Exact(b\"rt-lojban\"), tags: &[t(b\"JBO \")] },",
        "    Branch { first: b'c', cond: Cond::LangMatches(b\"do-hant-mo\"), tags: &[t(b\"ZHTM\"), t(b\"ZHH \")] },",
        "    Branch { first: b'c', cond: Cond::PrefixSubtag(b\"do-\", b\"-hk\"), tags: &[t(b\"ZHH \")] },",
        "    (t(b\"KGE \"), b\"und-Geok\"),",
    ] {
        assert!(out.contains(want), "missing `{want}` in\n{out}");
    }
}

/// `SAMPLE` with `from` replaced by `to`; `from` must be in it once.
fn changed(from: &str, to: &str) -> String {
    assert_eq!(SAMPLE.matches(from).count(), 1, "{from}");
    SAMPLE.replace(from, to)
}

fn fails(text: &str, why: &str) {
    let e = parse(text).unwrap_err();
    assert!(e.contains(why), "`{e}` does not contain `{why}`");
}

#[test]
fn an_unknown_condition_fails() {
    fails(
        &changed(
            "if (0 == strcmp (&lang_str[1], \"rt-lojban\"))",
            "if (0 == strcasecmp (&lang_str[1], \"rt-lojban\"))",
        ),
        "unknown shape",
    );
    fails(
        &changed(
            "if (lang_matches (&lang_str[1], limit, \"do-hant-mo\", 10))",
            "if (lang_matches (&lang_str[1], limit, \"do-hant-mo\", 10) || x)",
        ),
        "unknown shape",
    );
}

#[test]
fn a_length_that_does_not_match_the_string_fails() {
    fails(
        &changed(
            "subtag_matches (p, limit, \"-fonnapa\", 8)",
            "subtag_matches (p, limit, \"-fonnapa\", 7)",
        ),
        "unknown shape",
    );
    fails(
        &changed("\"do-hant-mo\", 10", "\"do-hant-mo\", 9"),
        "unknown shape",
    );
    fails(&changed("\"do-\", 3)", "\"do-\", 2)"), "unknown shape");
}

#[test]
fn another_offset_into_the_language_fails() {
    fails(
        &changed(
            "strcmp (&lang_str[1], \"rt-lojban\")",
            "strcmp (&lang_str[2], \"rt-lojban\")",
        ),
        "unknown shape",
    );
    fails(
        &changed(
            "subtag_matches (lang_str, limit, \"-hk\", 3)",
            "subtag_matches (p, limit, \"-hk\", 3)",
        ),
        "unknown shape",
    );
    fails(
        &changed(
            "subtag_matches (p, limit, \"-fonnapa\", 8)",
            "subtag_matches (lang_str, limit, \"-fonnapa\", 8)",
        ),
        "unknown shape",
    );
}

#[test]
fn an_unknown_result_fails() {
    fails(
        &changed(
            "tags[0] = HB_TAG('J','B','O',' ');",
            "tags[1] = HB_TAG('J','B','O',' ');",
        ),
        "unknown shape",
    );
    fails(
        &changed(
            "for (i = 0; i < 2 && i < *count; i++)",
            "for (i = 0; i < 3 && i < *count; i++)",
        ),
        "unknown shape",
    );
    fails(
        &changed(
            "      tags[0] = HB_TAG('Z','H','H',' ');  /* Chinese, Traditional, Hong Kong SAR */\n      *count = 1;\n      return true;\n    }\n    break;",
            "      tags[0] = HB_TAG('Z','H','H',' ');  /* Chinese, Traditional, Hong Kong SAR */\n      *count = 2;\n      return true;\n    }\n    break;",
        ),
        "expected `*count = 1;`",
    );
}

#[test]
fn an_unknown_line_fails() {
    fails(
        &changed("out:\n", "out:\n  lang_str++;\n"),
        "expected `switch (lang_str[0])`",
    );
    fails(
        &changed(
            "    break;\n  }\n  return false;",
            "    break;\n  default:\n    break;\n  }\n  return false;",
        ),
        "unknown shape",
    );
    fails(
        &changed(
            "  HB_TAG('z','n','d',' '),",
            "  HB_TAG('z','n','d',' '),\n  HB_TAG_NONE,",
        ),
        "unknown shape",
    );
    fails(
        &changed(
            "    return hb_language_from_string (\"alt\", -1);",
            "    return hb_language_from_string (\"alt\", 3);",
        ),
        "unknown shape",
    );
    fails(
        &changed("#endif /* HB_OT_TAG_TABLE_HH */", ""),
        "end of the header",
    );
    fails(&format!("{SAMPLE}int x;\n"), "unknown shape");
}

#[test]
fn unsorted_tables_fail() {
    fails(
        &changed(
            "HB_TAG('a','b','a',' '),\t/* Abé",
            "HB_TAG('z','z','z',' '),\t/* Abé",
        ),
        "ot_languages3_blocked is not sorted",
    );
    fails(&changed("0,\t2},", "1,\t2},"), "out of range");
}

#[test]
fn comments_and_whitespace_are_dropped() {
    let lines = code_lines("a  /* x */  b\n/* one\n two */ c\t\td // e\n\n").unwrap();
    let texts: Vec<&str> = lines.iter().map(|l| l.text.as_str()).collect();
    assert_eq!(texts, ["a b", "c d"]);
    assert_eq!(lines[1].no, 3);
    assert!(code_lines("'a\\'").is_err());
}

#[test]
fn the_commit_comes_from_the_lock_file() {
    let lock = "# x\nharfbuzz https://github.com/harfbuzz/harfbuzz abc\nfreetype u def\n";
    assert_eq!(lock_commit(lock, "harfbuzz").unwrap(), "abc");
    assert!(lock_commit(lock, "other").is_err());
}

/// The pinned header (fetched by scripts/fetch-testdata.sh) is read
/// whole.
#[test]
fn the_pinned_header_is_read() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../target/testdata/harfbuzz/src/hb-ot-tag-table.hh"
    );
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("{path}: {e}; run scripts/fetch-testdata.sh"));
    let table = parse(&text).unwrap();
    assert!(table.languages2.len() > 150);
    assert!(table.languages3.len() > 500);
    assert_eq!(table.complex_subtags.len(), 10);
    assert!(table.complex.len() > 100);
    assert!(
        table
            .complex
            .iter()
            .any(|b| matches!(&b.cond, Cond::PrefixSubtag(p, s) if p == "h-" && s == "-tw"))
    );
    assert!(
        table
            .ambiguous
            .iter()
            .any(|(t, l)| t == b"ZHTM" && l == "zh-MO")
    );
}
